class SporadicTask:
    def __init__(self, C, D, T):
        self.C = C  # Worst-case execution time
        self.D = D  # Relative deadline
        self.T = T  # Minimum inter-arrival time (period)

def is_constrained_deadline_system(task_set):
    for task_i in task_set:
        if task_i.D > task_i.T:
            return False
    return True

def is_implicit_deadline_system(task_set):
    for task_i in task_set:
        if task_i.D != task_i.T:
            return False
    return True

