def calculate_task_utilization(task_i):
    return task_i.C / task_i.T

def calculate_system_utilization(task_set):
    u_sum_tau = 0
    u_max_tau = 0
    for task_i in task_set:
        u_i = calculate_task_utilization(task_i)
        u_sum_tau += u_i
        if u_i > u_max_tau:
            u_max_tau = u_i
    return u_sum_tau, u_max_tau

def calculate_task_density(task_i):
    return task_i.C / task_i.D

def calculate_system_density(task_set):
    delta_sum_tau = 0
    delta_max_tau = 0
    for task_i in task_set:
        delta_i = calculate_task_density(task_i)
        delta_sum_tau += delta_i
        if delta_i > delta_max_tau:
            delta_max_tau = delta_i
    return delta_sum_tau, delta_max_tau

import math

def DBF(task_i, t):
    if t < task_i.D:
        return 0
    # Number of jobs fully contained within the interval [0, t] with deadlines <= t
    num_jobs = math.floor((t - task_i.D) / task_i.T) + 1
    return max(0, num_jobs * task_i.C)

def calculate_system_load(task_set):
    # In practice, t is checked at specific 'critical' points, not all t > 0
    # This is a conceptual sketch.
    max_load = 0
    # For a practical implementation, iterate over critical values of t
    # e.g., t = D_i + k*T_i for all tasks and k
    for t in get_critical_t_values(task_set):
        total_demand_at_t = 0
        for task_i in task_set:
            total_demand_at_t += DBF(task_i, t)
        if t > 0:
            current_load = total_demand_at_t / t
            if current_load > max_load:
                max_load = current_load
    return max_load

class Job:
    def __init__(self, arrival_time, deadline, execution_time, task_id):
        self.arrival_time = arrival_time
        self.deadline = deadline
        self.execution_time = execution_time
        self.task_id = task_id
        self.priority = self._assign_priority() # Priority assigned at arrival

    def _assign_priority(self):
        # Example for EDF: earlier deadline means higher priority
        return self.deadline

    def get_priority(self):
        return self.priority

