def I1_no_carry_in(task_i, task_k, A_k, D_k, C_k):
    interval_length = A_k + D_k - C_k
    if task_i.id != task_k.id:
        return min(DBF(task_i, interval_length), interval_length)
    else:
        # For the task k itself, its own job arriving at t_a doesn't contribute
        # to work *before* t_a or in Gamma_k (which is after t_a). 
        # The paper's formula for i=k is min(DBF(tau_i, A_k + D_k) - C_k, A_k).
        # This implies that the work of tau_k's job arriving at t_a is excluded.
        # The A_k bound is for work in [t_o, t_a).
        return min(DBF(task_i, A_k + D_k) - C_k, A_k)

