def calculate_C_sigma(task_set, m):
    if m <= 1:
        return 0
    C_values = [task.C for task in task_set]
    C_values.sort(reverse=True)
    # Sum the (m-1) largest C_i values
    return sum(C_values[:m-1])

def check_load_condition(task_set, m):
