def calculate_Ak_bound(task_set, task_k, m):
    u_sum_tau, _ = calculate_system_utilization(task_set)
    if m - u_sum_tau <= 0:
        # If total utilization >= m, the system is trivially unschedulable
        # or the bound is infinite, indicating no finite A_k can satisfy.
        return float('inf') 

    c_sigma = calculate_C_sigma(task_set, m)

    sum_Ti_Di_Ui = 0
    for task_i in task_set:
        sum_Ti_Di_Ui += (task_i.T - task_i.D) * (task_i.C / task_i.T)

    numerator = c_sigma - task_k.D * (m - u_sum_tau) + sum_Ti_Di_Ui + m * task_k.C
    denominator = m - u_sum_tau

    return numerator / denominator

