import math

def get_critical_Ak_values(task_set, task_k, m):
    max_Ak = calculate_Ak_bound(task_set, task_k, m)
    critical_points = {0} # Always check A_k = 0

    for task_i in task_set:
        # DBF(tau_i, t) changes when t - D_i is a multiple of T_i
        # So, A_k + D_k - D_i = k * T_i
        # A_k = k * T_i + D_i - D_k
        for k in range(math.ceil((task_k.D - task_i.D) / task_i.T), 
                       math.floor((max_Ak + task_k.D - task_i.D) / task_i.T) + 2):
            candidate_Ak = k * task_i.T + task_i.D - task_k.D
            if 0 <= candidate_Ak <= max_Ak:
                critical_points.add(candidate_Ak)

    return sorted(list(critical_points))

def global_edf_schedulability_test_pseudopolynomial(task_set, m):
